package projects.elevatorsystem;

import java.util.ArrayList;
import java.util.List;

public class Building {
    private final List<Integer> floors;
    private final List<Elevator> elevators;
    private final ElevatorController controller;

    public Building() {
        this.floors = new ArrayList<>();
        this.elevators = new ArrayList<>();
        this.controller = new ElevatorController();
        this.controller.setBuilding(this);
    }

    public void addFloor(int floor){
        this.floors.add(floor);
    }

    public void addElevator(Elevator elevator){
        this.elevators.add(elevator);
    }

    public List<Integer> getFloors(){
        return this.floors;
    }

    public List<Elevator> getElevators(){
        return this.elevators;
    }

    public Elevator getElevator(DirectionEnum direction, int currFloor){
        return this.controller.getElevator(direction, currFloor);
    }

    public void run(Elevator elevator){
        this.controller.run(elevator);
    }

}

package projects.elevatorsystem;

/**
 * Direction
 */
public enum DirectionEnum {
    UP,
    DOWN,
    PAUSE
}

package projects.elevatorsystem;

import java.util.*;

public class Elevator {
    private final int id;
    private final Set<Integer> stops;
    private final DirectionEnum direction;
    private int currentFloor;

    public Elevator(int id) {
        this.id = id;
        this.stops = new TreeSet<>();
        this.direction = DirectionEnum.PAUSE;
        this.currentFloor = 0;
    }

    public int getId(){
        return this.id;
    }

    public boolean isElevatorFree(){
        return this.direction == DirectionEnum.PAUSE;
    }

    public boolean hasStops(){
        return !this.stops.isEmpty();
    }

    public boolean hasStop(int floor){
        return this.stops.contains(floor);
    }

    public DirectionEnum getDirection() {
        return this.direction;
    }

    public synchronized void addStop(int floor) {
        stops.add(floor);
    }

    public synchronized void removeStop(int floor) {
        stops.remove(floor);
    }

    public void halt(int floor){
        System.err.println("Stopping at floor -> " + floor);
        this.removeStop(floor);
    }

    public void setCurrentFloor(int currentFloor){
        this.currentFloor = currentFloor;
    }

    public int getCurrentFloor(){
        return this.currentFloor;
    }
}

package projects.elevatorsystem;

import java.util.*;

public class ElevatorController {
    private Building building;
    private final Set<Elevator> movingElevators;

    public ElevatorController() {
        this.building = null;
        this.movingElevators = new TreeSet<>();
    }

    public void setBuilding(Building building){
        this.building = building;
    }

    public Elevator getElevator(DirectionEnum direction, int currentFloor) {
        Elevator closestElevator = null;
        int closestDistance = this.building.getFloors().size() + 1;
        for (Elevator elevator : this.building.getElevators()) {
            int distance = elevator.getCurrentFloor() - currentFloor;
            if(distance > 0 && closestDistance > distance){
                closestDistance = distance;
                closestElevator = elevator;
            }
        }
        return closestElevator;
    }

    public void run(Elevator elevator){
        this.movingElevators.add(elevator);
        this.runElevators();
    }

    public void runElevators(){
        List<Elevator> availableElevators = (List<Elevator>) this.movingElevators;
        while(!availableElevators.isEmpty()){
            List<Elevator> newAvailableElevators = new ArrayList<>();
            for (Elevator elevator : availableElevators) {
                int currFloor = elevator.getCurrentFloor();
                if(elevator.hasStop(currFloor)){
                    elevator.halt(currFloor);
                } else {
                    elevator.setCurrentFloor(currFloor-1);
                }
                if(elevator.hasStops()){
                    newAvailableElevators.add(elevator);
                }
            }
            availableElevators = newAvailableElevators;
        }
    }
}

package projects.elevatorsystem;

public class Main {
    public static void main(String[] args) {
        Building building = new Building();
        for (int floor = 0; floor < 10; floor++) {
            building.addFloor(floor);
        }
        for (int elevatorId = 0; elevatorId < 2; elevatorId++) {
            Elevator elevator = new Elevator(elevatorId);
            building.addElevator(elevator);
        }
        Elevator elevator = building.getElevator(DirectionEnum.UP, 0);
        building.run(elevator);
    }
}

